actions.action:
// Economic nexus established per Wayfair - filing required
// FL threshold: $50,000 (lower than typical $100K)
// Apportionment will be calculated by tables 7000-7500

// No nexus - no filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate Florida state additions
            double additions = 0.0;

            // FL addition: Interest on U.S. government obligations
            // (Exempt from federal tax but taxable to FL)
            // additions += revenue.federal_bond_interest;

            // FL addition: State income tax refunds included in federal income
            // (FL has no state income tax for individuals, but this can apply to corps)
            // additions += revenue.state_tax_refund;

            // FL addition: IRC § 78 gross-up for foreign tax credit
            // additions += revenue.section_78_gross_up;

            apportionment.state_additions = additions;

            // Calculate Florida state subtractions
            double subtractions = 0.0;

            // FL subtraction: Municipal bond interest from other states
            // (Taxable federally but exempt from FL tax for FL bonds)
            // subtractions += revenue.other_state_municipal_interest;

            // FL subtraction: Certain dividend income
            // (FL allows subtraction for certain dividends under FL Statute § 220.13)
            // subtractions += revenue.qualified_dividends_fl_exempt;

            // FL subtraction: State NOL deduction
            // (FL has its own NOL rules separate from federal)
            // subtractions += result.fl_nol_deduction;

            apportionment.state_subtractions = subtractions;

            // Florida uses 5.5% flat rate
            apportionment.state_tax =
              apportionment.state_taxable_income * apportionment.state_tax_rate;

            // Subtract Florida state credits
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
